def expand(s: str, left: int, right: int) -> int:
    """Grows a palindrome outward from its middle and returns its length."""
    while left >= 0 and right < len(s) and s[left] == s[right]:
        left -= 1
        right += 1
    return right - left - 1


def longest_palindrome(s: str) -> str:
    start, best = 0, 0
    for i in range(len(s)):
        # An odd-length middle is one letter, an even-length middle is two.
        for length in (expand(s, i, i), expand(s, i, i + 1)):
            if length > best:
                start, best = i - (length - 1) // 2, length
    return s[start : start + best]


s = input().strip()
print(longest_palindrome(s))

